[library](https://rdrr.io/r/base/library.html)(english)
cleanup <- function(s){
 s <- [str_remove_all](https://stringr.tidyverse.org/reference/str_remove.html)(s, "inches|in|''|\"|cm|and") |> 
 [str_trim](https://stringr.tidyverse.org/reference/str_trim.html)() |>
 [str_to_lower](https://stringr.tidyverse.org/reference/case.html)()
 for (i in 0:11) {
 s <- [str_replace_all](https://stringr.tidyverse.org/reference/str_replace.html)(s, [words](https://rdrr.io/pkg/english/man/words.html)(i), [as.character](https://rdrr.io/r/base/character.html)(i))
 }
 [return](https://rdrr.io/r/base/function.html)(s)
}
